package com.example.bluetoothtest

/**
 * The device-family decisions exactly as they were before DevicePolicyRegistry (master 181d786),
 * copied verbatim and wrapped in this object; calls to the object's own helpers are qualified.
 * DeviceFamilyPolicyMigrationTest compares them with the registry-backed functions. Generated by
 * the migration; delete it together with that test.
 */
@Suppress("UNUSED_PARAMETER", "unused")
internal object PreRegistryPolicyOracle {
    fun privateCallVideoSettings(
        selected: VideoSettings,
        transport: BluetoothTransportOption,
        fingerprint: BluetoothStackFingerprint? = null,
        preserveSelectedBitrate: Boolean = false,
    ): VideoSettings {
        val perDirectionKbps = when (transport) {
            BluetoothTransportOption.CLASSIC_RFCOMM -> 250
            BluetoothTransportOption.BLE_L2CAP -> 200
            BluetoothTransportOption.BLE_GATT -> 180
        }
        val transportLimited = selected.copy(
            bitRate = if (preserveSelectedBitrate) selected.bitRate else minOf(selected.bitRate, perDirectionKbps * 1_000),
        )
        val legacyGatt = transport == BluetoothTransportOption.BLE_GATT &&
            fingerprint != null && legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L
        val legacyCoc = transport == BluetoothTransportOption.BLE_L2CAP &&
            fingerprint != null && legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L
        val legacyRfcomm = transport == BluetoothTransportOption.CLASSIC_RFCOMM &&
            fingerprint != null && legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L
        val legacyMsmnile = fingerprint?.let { PreRegistryPolicyOracle.isLegacyQualcommMsmnileStack(it) } == true
        val legacyAtollCoc = legacyCoc && fingerprint?.let { PreRegistryPolicyOracle.isLegacyQualcommAtollStack(it) } == true
        return if (legacyGatt || legacyCoc || legacyMsmnile) {
            transportLimited.copy(
                resolution = if (
                    transportLimited.resolution.width * transportLimited.resolution.height > 426 * 240
                ) {
                    VideoResolution(426, 240, "240p")
                } else {
                    transportLimited.resolution
                },
                fps = minOf(
                    transportLimited.fps,
                    if (legacyCoc && !legacyMsmnile && !legacyAtollCoc) 20 else 15,
                ),
                bitRate = if (preserveSelectedBitrate) transportLimited.bitRate else minOf(
                    transportLimited.bitRate,
                    when {
                        legacyGatt -> 150_000
                        legacyMsmnile -> MSMNILE_COC_BITRATE_KBPS * 1_000
                        legacyAtollCoc -> ATOLL_COC_SEND_BITRATE_KBPS * 1_000
                        else -> CONSTRAINED_COC_BITRATE_KBPS * 1_000
                    },
                ),
            )
        } else if (legacyRfcomm) {
            transportLimited.copy(
                resolution = if (
                    transportLimited.resolution.width * transportLimited.resolution.height > 640 * 360
                ) {
                    VideoResolution(640, 360, "360p")
                } else {
                    transportLimited.resolution
                },
                fps = minOf(transportLimited.fps, 15),
                bitRate = if (preserveSelectedBitrate) transportLimited.bitRate else
                    minOf(transportLimited.bitRate, LEGACY_RFCOMM_SEND_BITRATE_KBPS * 1_000),
            )
        } else {
            transportLimited
        }
    }

    /**
     * DEBUG `test_preserve_call_bitrate` keeps an exact-rate call at the selected bitrate instead of the
     * per-direction starting budget, to challenge that budget. GATT had it first; Classic (250 kbps
     * budget, EDR measured 1.15-1.19 Mbps payload) got it 2026-10-09. CoC keeps its legacy protections.
     */
    fun debugPreserveCallBitrateApplies(transport: BluetoothTransportOption): Boolean =
        transport == BluetoothTransportOption.BLE_GATT || transport == BluetoothTransportOption.CLASSIC_RFCOMM

    fun privateCallDecodeRestricted(
        fingerprint: BluetoothStackFingerprint,
        transport: BluetoothTransportOption,
    ): Boolean = legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L &&
        (transport != BluetoothTransportOption.BLE_L2CAP || isLegacyQualcommMsmnileStack(fingerprint))

    fun privateCallDecodeCodecMask(
        fingerprint: BluetoothStackFingerprint,
        transport: BluetoothTransportOption,
        defaultDecodeCodecMask: Int,
    ): Int {
        val vp9 = defaultDecodeCodecMask and NodeCapabilities.CODEC_VP9
        val needsVp9Compatibility = privateCallDecodeRestricted(fingerprint, transport)
        return if (needsVp9Compatibility && vp9 != 0) {
            vp9
        } else {
            defaultDecodeCodecMask
        }
    }

    fun privateCallCapabilityMaxBitrateKbps(
        transport: BluetoothTransportOption,
        fingerprint: BluetoothStackFingerprint,
        defaultMaxBitrateKbps: Int,
    ): Int =
        when {
            isLegacyQualcommMsmnileStack(fingerprint) &&
                transport in setOf(
                    BluetoothTransportOption.BLE_L2CAP,
                    BluetoothTransportOption.CLASSIC_RFCOMM,
                ) -> MSMNILE_COC_BITRATE_KBPS
            transport == BluetoothTransportOption.BLE_L2CAP &&
                legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L ->
                CONSTRAINED_COC_BITRATE_KBPS
            transport == BluetoothTransportOption.CLASSIC_RFCOMM &&
                legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L ->
                CONSTRAINED_RFCOMM_BITRATE_KBPS
            else -> defaultMaxBitrateKbps
        }

    fun privateCallAudioBitRate(
        transport: BluetoothTransportOption,
        fingerprint: BluetoothStackFingerprint,
        peerMaxBitrateKbps: Int? = null,
    ): Int = if (
        transport == BluetoothTransportOption.BLE_GATT &&
            legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L ||
            transport == BluetoothTransportOption.BLE_L2CAP && (
                legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L ||
                    peerMaxBitrateKbps != null &&
                    peerMaxBitrateKbps in 1..CONSTRAINED_COC_BITRATE_KBPS
                ) ||
            transport == BluetoothTransportOption.CLASSIC_RFCOMM && (
                legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L ||
                    peerMaxBitrateKbps != null &&
                    peerMaxBitrateKbps in 1..CONSTRAINED_RFCOMM_BITRATE_KBPS
                )
    ) {
        16_000
    } else {
        StreamProtocol.AUDIO_BIT_RATE
    }

    /**
     * Relayed call video. The legacy cap (15 FPS, 110 kbps) predates any relay measurement: it is in the
     * first local commit and DECISIONS records it as a starting budget, not a ceiling (CoC S24 -> M31 ->
     * S22). With [measuredBudgetBps] (experimental, DebugTunables.relayedCallMeasuredCap) the bitrate
     * cap follows [relayedCallMeasuredBudgetBps] instead, never below the legacy cap. FPS stays at 15:
     * every relayed measurement so far ran at 15 FPS, and FPS is not what this cap questions.
     */
    fun privateCallVideoSettingsForRoute(
        directSettings: VideoSettings,
        relayHops: Int,
        measuredBudgetBps: Int? = null,
    ): VideoSettings = if (relayHops == 0) {
        directSettings
    } else {
        directSettings.copy(
            fps = minOf(directSettings.fps, RELAYED_CALL_MAX_FPS),
            bitRate = minOf(
                directSettings.bitRate,
                maxOf(RELAYED_CALL_LEGACY_BITRATE_BPS, measuredBudgetBps ?: RELAYED_CALL_LEGACY_BITRATE_BPS),
            ),
        )
    }

    internal const val RELAYED_CALL_MAX_FPS = 15
    internal const val RELAYED_CALL_LEGACY_BITRATE_BPS = 110_000

    /**
     * A relay's single radio carries both of its adjacent links, each in both call directions: four
     * copies of one direction's rate share its airtime, where a direct call has two
     * ([CallStartRate.MEASURED_LINK_SHARE], half less 15% headroom). Measured basis: a one-way stream
     * relay carried 433-458 kbps in and out (DECISIONS CoC/GATT/Classic CBR 375-400), about half of
     * the 0.88-1.0 Mbps those phones measure, so one relayed flow fits about a quarter of the link.
     */
    internal const val RELAYED_CALL_LINK_SHARE = CallStartRate.MEASURED_LINK_SHARE / 2

    /** Video budget of one relayed call direction from this phone's fresh measured link, or null. */
    fun relayedCallMeasuredBudgetBps(measuredLinkKbps: Int?, audioBps: Int): Int? =
        measuredLinkKbps?.takeIf { it > 0 }?.let { (it * 1_000L * RELAYED_CALL_LINK_SHARE).toInt() - audioBps }

    fun privateCallVideoSettingsForPeer(
        settings: VideoSettings,
        transport: BluetoothTransportOption,
        peerMaxBitrateKbps: Int?,
    ): VideoSettings {
        val constrainedMaximumFps = when {
            peerMaxBitrateKbps == null -> return settings
            transport == BluetoothTransportOption.BLE_L2CAP &&
                peerMaxBitrateKbps in 1..CONSTRAINED_COC_BITRATE_KBPS ->
                if (peerMaxBitrateKbps <= MSMNILE_COC_BITRATE_KBPS) 15 else 20
            transport == BluetoothTransportOption.CLASSIC_RFCOMM &&
                peerMaxBitrateKbps in 1..CONSTRAINED_RFCOMM_BITRATE_KBPS ->
                if (peerMaxBitrateKbps <= MSMNILE_COC_BITRATE_KBPS) 15 else 30
            else -> return settings
        }
        return settings.copy(
            resolution = if (
                transport == BluetoothTransportOption.CLASSIC_RFCOMM &&
                peerMaxBitrateKbps > MSMNILE_COC_BITRATE_KBPS
            ) {
                settings.resolution
            } else if (settings.resolution.width * settings.resolution.height > 426 * 240) {
                VideoResolution(426, 240, "240p")
            } else {
                settings.resolution
            },
            fps = minOf(settings.fps, constrainedMaximumFps),
            bitRate = minOf(settings.bitRate, peerMaxBitrateKbps * 1_000),
        )
    }

    /** One call audio record from 1 (as is), 2 (pair) or 3-20 (batch) consecutive Opus access units. */
    fun combineCallAudio(packets: List<StreamProtocol.Packet>): StreamProtocol.Packet = when (packets.size) {
        0 -> throw IllegalArgumentException("No call audio to combine")
        1 -> packets[0]
        2 -> StreamProtocol.pairAudioPackets(packets[0], packets[1])
        else -> StreamProtocol.batchAudioPackets(packets)
    }

    fun pairPrivateCallAudioForRoute(
        transport: BluetoothTransportOption,
        relayHops: Int,
        fingerprint: BluetoothStackFingerprint? = null,
        peerMaxBitrateKbps: Int? = null,
    ): Boolean =
        transport == BluetoothTransportOption.BLE_L2CAP && (
            relayHops > 0 ||
                fingerprint != null && legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L ||
                peerMaxBitrateKbps != null &&
                peerMaxBitrateKbps in 1..CONSTRAINED_COC_BITRATE_KBPS
            ) ||
            transport == BluetoothTransportOption.BLE_GATT &&
            fingerprint != null && legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L ||
            transport == BluetoothTransportOption.CLASSIC_RFCOMM && (
                fingerprint != null && legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L ||
                    peerMaxBitrateKbps != null &&
                    peerMaxBitrateKbps in 1..CONSTRAINED_RFCOMM_BITRATE_KBPS
                )

    fun privateCallAudioBatchSizeForRoute(
        transport: BluetoothTransportOption,
        relayHops: Int,
        fingerprint: BluetoothStackFingerprint? = null,
        peerMaxBitrateKbps: Int? = null,
        /** Experimental legacy low delay (see [privateCallLegacyLowDelay]); false keeps the 20-packet batch. */
        legacyLowDelay: Boolean = false,
    ): Int = when {
        transport == BluetoothTransportOption.BLE_L2CAP &&
            !privateCallLegacyLowDelay(legacyLowDelay, relayHops) &&
            pairPrivateCallAudioForRoute(transport, relayHops, fingerprint, peerMaxBitrateKbps) -> 20
        pairPrivateCallAudioForRoute(transport, relayHops, fingerprint, peerMaxBitrateKbps) -> 2
        else -> 1
    }

    /**
     * Experimental legacy low delay (default off; DEBUG `test_call_legacy_low_delay`), direct calls
     * only. On a legacy-constrained call route (a legacy Qualcomm phone, or a peer that declares a
     * constrained CoC/Classic receive limit) audio is sent in 2-packet (40 ms) records instead of
     * 20-packet (400 ms) batches, and incoming media plays with the normal call delay (250-600 ms)
     * instead of the constrained one (500-800 ms).
     *
     * Measured cost of the protection (calls-noloss-m31asus-51cc8028, CoC, both directions and voice
     * calls): audio batch fill p50 380 ms, playout 500 ms growing to 800 ms, so about 0.9-1.2 s one way
     * before radio time, against ITU-T G.114's 400 ms planning limit. The 20-packet batch has no
     * measured reason of its own: the record-rate overload that justified batching was on a relayed
     * CoC route, and 2-packet pairs fixed it there (25 audio records/s, 641/647 frames at 15 FPS,
     * decoder 0; DECISIONS "Legacy-family protections"). The same ASUS carries 50 audio records/s
     * plus video in streams. Relayed calls keep the batch.
     */
    fun privateCallLegacyLowDelay(enabled: Boolean, relayHops: Int): Boolean = enabled && relayHops == 0

    fun privateCallVideoQueueCapacity(
        fps: Int,
        playbackDelayProfile: PlaybackDelayProfile,
        transport: BluetoothTransportOption,
        fingerprint: BluetoothStackFingerprint? = null,
    ): Int = playbackDelayProfile.videoQueueCapacity(fps) +
        if (
            transport == BluetoothTransportOption.BLE_L2CAP ||
            transport == BluetoothTransportOption.CLASSIC_RFCOMM &&
            fingerprint != null && legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L
        ) 8 else 0

    fun privateCallMediaFlushIntervalMs(
        transport: BluetoothTransportOption,
        fingerprint: BluetoothStackFingerprint,
        peerMaxBitrateKbps: Int?,
    ): Long = when {
        transport == BluetoothTransportOption.BLE_GATT ->
            legacyQualcommGattCallFlushIntervalMs(fingerprint)
        transport == BluetoothTransportOption.BLE_L2CAP && (
            legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L ||
                peerMaxBitrateKbps != null &&
                peerMaxBitrateKbps in 1..CONSTRAINED_COC_BITRATE_KBPS
            ) -> 20L
        transport == BluetoothTransportOption.CLASSIC_RFCOMM && (
            legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L ||
                peerMaxBitrateKbps != null &&
                peerMaxBitrateKbps in 1..CONSTRAINED_RFCOMM_BITRATE_KBPS
            ) -> 20L
        else -> 0L
    }

    fun privateCallPlaybackDelayProfile(
        selected: PlaybackDelayProfile,
        transport: BluetoothTransportOption,
        fingerprint: BluetoothStackFingerprint,
        peerMaxBitrateKbps: Int?,
        /** Experimental legacy low delay for this (direct) call; see [privateCallLegacyLowDelay]. */
        legacyLowDelay: Boolean = false,
    ): PlaybackDelayProfile = selected.forCall(
        constrainedLink = !legacyLowDelay && when (transport) {
            BluetoothTransportOption.CLASSIC_RFCOMM ->
                legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L ||
                    peerMaxBitrateKbps != null &&
                    peerMaxBitrateKbps in 1..CONSTRAINED_RFCOMM_BITRATE_KBPS
            BluetoothTransportOption.BLE_L2CAP ->
                legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L ||
                    peerMaxBitrateKbps != null &&
                    peerMaxBitrateKbps in 1..CONSTRAINED_COC_BITRATE_KBPS
            BluetoothTransportOption.BLE_GATT -> false
        },
    )

    /**
     * Decode mask this phone advertises in its END-TO-END call hello (the link hello keeps
     * [privateCallDecodeCodecMask]). A legacy Qualcomm phone restricted to VP9 advertises its real
     * decoders plus [NodeCapabilities.DECODE_PREFERS_VP9]; senders honour the preference whenever they
     * can encode VP9 ([privateCallCodecForPeer]), so VP9-capable peers still send VP9, and AV1-only peers
     * (A15s, Xiaomi: no VP9 encoder; Android's CDD requires VP9 decoding, not encoding) send AV1 instead
     * of failing with "Peer cannot decode any locally available call codec".
     *
     * The decision uses only this phone's own decoders and the end-to-end hello, which relays copy
     * opaquely, so direct and relayed calls agree in both setup roles. The first version keyed on the
     * peer's link hello, which on a relayed call is the relay's (relaycall-915d7390b/0004: A15s -> S24
     * relay -> ASUS still failed). The ASUS decodes AV1 640x480 with 0 freezes in 12 stream cases
     * (bmaraw-ab-stream-9c121b30-m31asus-r1). [fallback] false is the control arm
     * (`test_call_codec_fallback=false`): VP9 only, exactly as before.
     */
    fun privateCallEndpointDecodeMask(
        restrictedMask: Int,
        platformMask: Int,
        fallback: Boolean,
    ): Int {
        val extra = platformMask and restrictedMask.inv() and CALL_CODEC_MASK
        return if (fallback && extra != 0) restrictedMask or extra or NodeCapabilities.DECODE_PREFERS_VP9 else restrictedMask
    }

    private const val CALL_CODEC_MASK = NodeCapabilities.CODEC_VP9 or NodeCapabilities.CODEC_AV1

    /**
     * The receiver's playout profile for this call. Experimental [lowDelayVoice]: a voice-only call on an
     * unconstrained link uses CALL_VOICE; video calls and constrained links (CALL_STABLE, whose audio
     * arrives in batches of up to 400 ms) keep [routeProfile].
     */
    fun privateCallReceiverPlaybackProfile(
        routeProfile: PlaybackDelayProfile,
        localCallType: CallType,
        lowDelayVoice: Boolean,
    ): PlaybackDelayProfile = if (
        lowDelayVoice && localCallType == CallType.VOICE && routeProfile != PlaybackDelayProfile.CALL_STABLE
    ) {
        PlaybackDelayProfile.CALL_VOICE
    } else {
        routeProfile
    }

    private const val MSMNILE_COC_BITRATE_KBPS = 110
    private const val ATOLL_COC_SEND_BITRATE_KBPS = 110
    private const val CONSTRAINED_COC_BITRATE_KBPS = 160
    private const val LEGACY_RFCOMM_SEND_BITRATE_KBPS = 200
    private const val CONSTRAINED_RFCOMM_BITRATE_KBPS = 250
    fun canRecoverPrivateCallVideoDecoder(decoderName: String, recoveryAttempts: Int): Boolean =
        decoderName.equals("c2.android.vp9.decoder", ignoreCase = true) && recoveryAttempts in 0..1

    fun isLegacyQualcommMsmnileStack(fingerprint: BluetoothStackFingerprint): Boolean {
        if (fingerprint.sdkInt > 32 || !fingerprint.hardware.equals("qcom", ignoreCase = true)) return false
        val board = fingerprint.board.lowercase()
        return board == "msmnile" || board.startsWith("sm8150")
    }

    fun isLegacyQualcommAtollStack(fingerprint: BluetoothStackFingerprint): Boolean {
        if (fingerprint.sdkInt > 32 || !fingerprint.hardware.equals("qcom", ignoreCase = true)) return false
        val board = fingerprint.board.lowercase()
        return board == "atoll" || board == "curtana" || board.startsWith("sm7125")
    }

    object LegacyQualcommClassicCompatibility {
        /** Compatibility rules are stack-family based. Manufacturer and model must never be inputs. */
        fun matches(
            transport: BluetoothTransportOption,
            fingerprint: BluetoothStackFingerprint,
        ): Boolean {
            if (transport != BluetoothTransportOption.CLASSIC_RFCOMM) return false
            return PreRegistryPolicyOracle.isLegacyQualcommMsmnileStack(fingerprint)
        }
    }

    fun useContinuousLowLatencyViewerDiscovery(
        transport: BluetoothTransportOption,
        fingerprint: BluetoothStackFingerprint,
        sourceSlotsFull: Boolean = false,
    ): Boolean = !LegacyQualcommClassicCompatibility.matches(transport, fingerprint) &&
        !(transport == BluetoothTransportOption.CLASSIC_RFCOMM && sourceSlotsFull)

    /**
     * A full source stops scanning for new viewer requests until a slot frees. LE sources share one
     * controller with their media links: continuous low-latency scanning while full cost 342 vs 27
     * lost source frames (VMAF 75 vs 97) in the matched GATT A/B, and full chain/fan-out sources
     * dropped 110-934 packets. Legacy msmnile Classic sources are included: their balanced scan still
     * left 300-530 ms delivery gaps at 500 kbps (ASUS -> S24, coverage input), the same symptom its
     * low-latency scan caused; the balanced rule still applies while slots remain.
     */
    @Suppress("UNUSED_PARAMETER")
    fun pauseClassicViewerDiscoveryAtCapacity(
        transport: BluetoothTransportOption,
        fingerprint: BluetoothStackFingerprint,
    ): Boolean = true

    /**
     * The stack fingerprint that private-call compatibility rules see: the one switch for every legacy
     * Qualcomm call protection on this phone (DeviceFamilyPolicy migration point).
     *
     * Matcher today: hardware `qcom` and API <= 32 ([legacyQualcommGattCallFlushIntervalMs]), with extra
     * msmnile/atoll rules. Evidence base: historical ASUS (msmnile/SM8150, API 30) and Redmi Note 9 Pro
     * (atoll, API 30) private-call failures before pacing (DECISIONS "Legacy-family protections").
     * No official source names these limits. Current counter-evidence: the same ASUS received native
     * AV1 640x480 at 300-1000 kbps over CoC and GATT with 0 freezes and a 14.3-14.8 FPS worst window
     * (bmaraw-ab-stream-9c121b30-m31asus-r1, 12 cases; c2.android.av1.decoder), while its calls are held
     * to 426x240-class geometry, 110 kbps on CoC, Opus 16, 400 ms audio batches and 500-800 ms playout.
     *
     * Experimental legacy relief (default off; DEBUG `test_call_legacy_relief`): returns a neutral
     * fingerprint, so none of the legacy call protections applies and this phone advertises its normal
     * receive limits. Relay and stream rules keep the real fingerprint. Confidence: low until the
     * phone A/B in docs/dev/testing.md.
     */
    fun privateCallStackFingerprint(
        current: BluetoothStackFingerprint = BluetoothStackFingerprint.current(),
        relief: Boolean = DebugTunables.callLegacyRelief,
    ): BluetoothStackFingerprint = if (relief) current.copy(hardware = "") else current

    fun legacyQualcommGattCallFlushIntervalMs(fingerprint: BluetoothStackFingerprint): Long =
        if (fingerprint.hardware.equals("qcom", ignoreCase = true) && fingerprint.sdkInt <= 32) 40L else 0L

    fun privateCallPreferredDecoderName(
        codecId: Int,
        fingerprint: BluetoothStackFingerprint,
    ): String? = "c2.android.vp9.decoder".takeIf {
        codecId == StreamProtocol.CODEC_VP9 &&
            legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L
    }

    fun privateCallCodec(
        selected: VideoCodec,
        available: List<VideoCodec>,
        fingerprint: BluetoothStackFingerprint,
        transport: BluetoothTransportOption,
    ): VideoCodec {
        val needsVp9Compatibility = selected.protocolId == StreamProtocol.CODEC_AV1 &&
            legacyQualcommGattCallFlushIntervalMs(fingerprint) > 0L &&
            (transport != BluetoothTransportOption.BLE_L2CAP || isLegacyQualcommMsmnileStack(fingerprint))
        if (!needsVp9Compatibility) return selected
        return available
            .filter { it.protocolId == StreamProtocol.CODEC_VP9 }
            .minByOrNull(VideoCodec::selectionPriority)
            ?: selected
    }


    // DeviceFamilyPolicy (the first registry), GattClientTeardown.deferredFor, CocListeners.sharedEnabledFor.
    fun leCocServerLeaks(fingerprint: BluetoothStackFingerprint): Boolean = fingerprint.sdkInt <= 29
    fun gattContextMapRace(fingerprint: BluetoothStackFingerprint): Boolean = fingerprint.sdkInt <= 30
    fun deferredFor(fingerprint: BluetoothStackFingerprint, override: Boolean?): Boolean =
        override ?: gattContextMapRace(fingerprint)
    fun sharedEnabledFor(fingerprint: BluetoothStackFingerprint, override: Boolean?): Boolean =
        override ?: leCocServerLeaks(fingerprint)
    fun leCocEattStrandedChannels(fingerprint: BluetoothStackFingerprint): Boolean = fingerprint.sdkInt in 31..33
    fun freshAclEnabledFor(fingerprint: BluetoothStackFingerprint, override: Boolean?): Boolean =
        override ?: leCocEattStrandedChannels(fingerprint)
    // BluetoothRestart.refusal.
    private const val LAST_APP_TOGGLE_SDK = 32
    fun refusal(sdkInt: Int, busyReason: String?, alreadyRunning: Boolean): String? = when {
        sdkInt > LAST_APP_TOGGLE_SDK -> "sdk_$sdkInt"
        alreadyRunning -> "already_running"
        busyReason != null -> "busy_$busyReason"
        else -> null
    }
    // VideoCodec.availableEncoders tie-break and OpusAudioDecoder ordering.
    fun encoderTieBreakRank(encoderName: String): Int = if (encoderName.startsWith("c2.")) 0 else 1
    fun opusDecoderPreferred(name: String): Boolean = name.startsWith("c2.android.")
}
